ts.size(1) == token_lora_mapping.size(0)\n    assert inputs.size(0) == len(lora_b_weights)\n\n    (slice_start_tensor, lora_ptr_tensor, lora_strides_d0_tensor,\n     lora_strides_d1_tensor, lora_strides_d2_tensor, hidden_sizes_tensor,\n     same_stride, MAX_N) = _get_lora_b_ptr(lora_b_weights, offset_start,\n                                           lora_ids.device)\n\n    # TODO tuning this config\n    K = lora_b_weights[0].shape[-1]  # K= rank\n\n    BLOCK_M = 64\n    BLOCK_N = 128\n    BLOCK_K = 16\n    EVEN_K = K % BLOCK_K == 0\n    ADD_INPUTS = add_inputs\n    CAST_TYPE = False\n\n    if inputs.dtype == torch.float32 and lora_b_weights[0].dtype in [\n            torch.float16,\n            torch.bfloat16,\n    ]:\n        CAST_TYPE = True\n    \n    # Get max tokens per lora for grid calculation\n    max_tokens_per_lora = torch.max(num_tokens_per_lora).item()\n    \n    grid = (\n        triton.cdiv(max_tokens_per_lora, BLOCK_M) * triton.cdiv(MAX_N, BLOCK_N),\n        len(lora_b_weights),\n        len(lora_b_weights),\n    )\n    _v1_expand_kernel[grid](\n        inputs,\n        lora_ptr_tensor,\n        output_tensor,\n        MAX_N,\n        K,\n        token_indices_sorted_by_lora_ids,\n        num_tokens_per_lora,\n        lora_token_start_loc,\n        lora_ids,\n        slice_start_tensor,\n        inputs.stride(0),\n        inputs.stride(1),\n        inputs.stride(2),\n        lora_strides_d0_tensor,\n        lora_strides_d1_tensor,\n        lora_strides_d2_tensor,\n        output_tensor.stride(0),\n        output_tensor.stride(1),\n        hidden_sizes_tensor,\n        BLOCK_M,\n        BLOCK_N,\n        BLOCK_K,\n        EVEN_K,\n        ADD_INPUTS,\n        CAST_TYPE,\n        len(lora_b_weights),\n        same_stride,\n    )\n    return"
