ad(lora_ids + cur_lora_idx)\n    if lora_index == -1:\n        return\n\n    # Calculate the actual token indices in the input tensor\n    # token_indices_sorted_by_lora_ids maps sorted position to original token index\n    cta_m_len = min(BLOCK_M, num_tokens_for_lora - (pid_m * BLOCK_M))\n    offset_m = tl.arange(0, BLOCK_M)\n    sorted_positions = lora_start + pid_m * BLOCK_M + tl.max_contiguous(\n        tl.multiple_of(offset_m % cta_m_len, BLOCK_M), BLOCK_M)\n    \n    # Load the actual token indices from the sorted mapping\n    ram = tl.load(token_indices_sorted_by_lora_ids + sorted_positions)\n\n    do_shrink_kernel(\n        pid_n,\n        pid_sk,\n        slice_id,\n        lora_index,\n        input_ptr,\n        lora_ptr,\n        out_ptr,\n        N,\n        K,\n        cta_m_len,\n        ram,\n        # input strides\n        input_d0_stride,\n        input_d1_stride,\n        # lora strides\n        lora_d0_stride,\n        lora_d1_stride,\n        lora_d2_stride,\n        # output strides\n        output_d0_stride,\n        output_d1_stride,\n        output_d2_stride,\n        scaling,\n        BLOCK_M,\n        BLOCK_N,\n        BLOCK_K,\n        EVEN_K,\n        SPLIT_K,\n        SLICE_NUM)",
        "_v1_shrink": "@torch.inference_mode()\ndef _v1_shrink(\n    inputs: torch.Tensor,  #  shape [num_tokens, hidden_size]\n    lora_a_weights: List[\n        torch.Tensor],  # shape [num_loras, lora_rank, hidden_size]\n    output_tensor: torch.Tensor,  # shape [num_slices, num_tokens, lora_rank]\n    token_lora_mapping: torch.Tensor,  # shape [num_tokens]\n    token_indices_sorted_by_lora_ids: torch.Tensor,  # shape [num_tokens] \n    num_tokens_per_lora: torch.Tensor,  # shape [max-loras + 1]\n    lora_token_start_loc: torch.Tensor,  # shape [max-loras + 2]\n    lora_ids: torch.Tensor,  # shape [max-loras + 1]\n    scaling: float,\n) -> None:\n    \"\"\"\n    V1 shrink operation for tokens not grouped by LoRA ID.\n    \n    Args:\n        inputs (torch.Tensor): input tensor, shape [num_tokens, hidden_size]\n        lora_a_weights (List[torch.Tensor]): lora'a weight, shape [num_loras, lora_rank, hidden_size]\n        output_tensor (torch.Tensor): output tensor, shape [num_slices, num_tokens, lora_rank]\n        token_lora_mapping (torch.Tensor): shape [num_tokens], maps each token to its LoRA ID\n        token_indices_sorted_by_lora_ids (torch.Tensor): shape [num_tokens], indices of tokens sorted by LoRA ID\n        num_tokens_per_lora (torch.Tensor): shape [max-loras + 1], number of tokens per LoRA\n        lora_token_start_loc (torch.Tensor): shape [max-loras + 2], start location of tokens for each LoRA\n        lora_ids (torch.Tensor): shape [max-loras + 1], LoRA IDs\n        scaling (float): Scaling factor.\n    \"\"\"\n    assert inputs.dtype == lora_a_weights[0].dtype\n    assert inputs.dtype in [torch.float16, torch.bfloat16]\n    for weight in lora_a_weights:\n        assert weight.dtype in [torch.float16, torch.bfloat16]\n\n    num_tokens = inputs.size(0)\n    assert inputs.size(0) == token_lora_mapping.size(0)\n    assert inputs.size(1) == lora_a_weights[0].size(-1)\n    assert inputs.is_contiguous()\n    assert output_tensor.is_contiguous()\n    \n    (lora_ptr_tensor, lora_strides_d0, lora_strides_d1,\n     lora_strides_d2) = _get_lora_a_ptr(lora_a_weights, lora_ids.device)\n    \n    # TODO tuning this config\n    N, K = lora_a_weights[0].shape[-2:]  # K=hidden_size,N=rank\n    BLOCK_M = 32\n    BLOCK_N = 16\n    BLOCK_K = 32\n    SPLIT_K = 8\n    EVEN_K = K % (BLOCK_K * SPLIT_K) == 0\n    \n    # Get max tokens per lora for grid calculation\n    max_tokens_per_lora = torch.max(num_tokens_per_lora).item()\n    \n    grid = (\n        triton.cdiv(max_tokens_per_lora, BLOCK_M) * triton.cdiv(N, BLOCK_N),\n        SPLIT_K * len(lora_a_weights),\n        len(lora_a_weights),\n    )\n    _v1_shrink_kernel[grid](\n        inputs,\n        lora_ptr_tensor,\n        output_tensor,\n        N,\n        K,\n        token_indices_sorted_by_lora_ids,\n        num_tokens_per_lora,\n        lora_token_start_loc,\n        lora_ids,\n        scaling,\n        inputs.stride(0),\n        inputs.stride(1),\n        lora_strides_d0,\n        lora_strides_d1,\n        lora_strides_d2,\n        output_tensor.stride(0),\n        output_tensor.stride(1),\n        output_tensor.stride(2),\n        BLOCK_M,\n        BLOCK_N,\n        BLOCK_K,\n        EVEN_K,\n        SPLIT_K,\n        len(lora_a_weights),\n    )\n    return"
    }
